@pragma('vm:entry-point')
int barcodeUnequalSplitCount(List<int> digits) {
  if (digits.length <= 1) return 0;
  int mid = digits.length ~/ 2;
  List<int> left = digits.sublist(0, mid);
  List<int> right = digits.sublist(mid);
  int leftSum = left.fold(0, (s, v) => s + v);
  int rightSum = right.fold(0, (s, v) => s + v);
  int count = leftSum < rightSum ? 1 : 0;
  return count + barcodeUnequalSplitCount(left) + barcodeUnequalSplitCount(right);
}

@pragma('vm:entry-point')
void main() {
  assert(barcodeUnequalSplitCount([1, 2]) == 1);
  assert(barcodeUnequalSplitCount([3, 2]) == 0);
  assert(barcodeUnequalSplitCount([]) == 0);
  print('All tests passed!');
}

tests:
