  final candidate = barcodeUnequalSplitCount;

  expect(candidate([]), 0);
  expect(candidate([5]), 0);
  expect(candidate([1, 2]), 1);
  expect(candidate([3, 2]), 0);
  expect(candidate([1, 2, 3]), 2);
  expect(candidate([3, 2, 1]), 0);
  expect(candidate([1, 1, 1, 1]), 0);
  expect(candidate([1, 2, 3, 4]), 3);
  expect(candidate([4, 3, 2, 1]), 0);
  expect(candidate([2, 1, 4, 3]), 1);
  expect(candidate([1, 2, 3, 4, 5, 6, 7, 8]), 7);
  expect(candidate([0, -1, 2, -3, 4, -5]), 3);
}

