import 'dart:math';

bool isWifiSignalDistributionEven(List<int> signals) {
  int poor = 0, fair = 0, good = 0;
  for (var s in signals) if (s < -80) poor++; else if (s <= -60) fair++; else good++;
  int maxC = max(poor, max(fair, good));
  int minC = min(poor, min(fair, good));
  return maxC - minC <= 1;
}

