@pragma('vm:entry-point')
bool followsBalconySeatResetPattern(List<int> blockedDays, int cycle) {
  var exactGapSeen = false;

  for (var i = 1; i < blockedDays.length; i++) {
    var gap = blockedDays[i] - blockedDays[i - 1];

    if (gap < cycle || gap > cycle + 1) {
      return false;
    }

    exactGapSeen = exactGapSeen || gap == cycle;
  }

  return exactGapSeen && blockedDays.length > 1;
}

@pragma('vm:entry-point')
