@pragma('vm:entry-point')
import 'dart:math';

bool isSolidOrchestraSection(List<List<int>> seats) {
  var seen = <String>{};
  int minX = 1 << 30, maxX = -(1 << 30);
  int minY = 1 << 30, maxY = -(1 << 30);
  for (var s in seats) {
    if (!seen.add('${s[0]},${s[1]}')) return false;
    minX = min(minX, s[0]);
    maxX = max(maxX, s[0]);
    minY = min(minY, s[1]);
    maxY = max(maxY, s[1]);
  }
  return seats.isNotEmpty &&
      seats.length == (maxX - minX + 1) * (maxY - minY + 1);
}

@pragma('vm:entry-point')
void main() {
  assert(isSolidOrchestraSection([[2, 3]]) == true);
  assert(isSolidOrchestraSection([[0, 0], [1, 0], [0, 1], [1, 1]]) == true);
  assert(isSolidOrchestraSection([[0, 0], [2, 0]]) == false);
  print('All tests passed!');
}

