@pragma('vm:entry-point')
int runLengthMazeChecksum(String maze) {
  int checksum = 0;
  final regex = RegExp(r'(\d+)([#.])');
  for (final match in regex.allMatches(maze)) {
    int count = int.parse(match.group(1)!);
    String type = match.group(2)!;
    if (type == '#') {
      checksum += count;
    } else if (type == '.') {
      checksum -= count;
    }
  }
  return checksum;
}

@pragma('vm:entry-point')
void main() {
  assert(runLengthMazeChecksum("") == 0);
  assert(runLengthMazeChecksum("5#3.") == 2);
  assert(runLengthMazeChecksum("2#2.1#1.") == 0);
  print('All tests passed!');
}

