bool isValidPasswordTypeBitmask(int bitmask) {
  int low = bitmask & 0xF;
  int cntLow = (low & 0x5) + ((low >> 1) & 0x5);
  cntLow = (cntLow & 0x3) + ((cntLow >> 2) & 0x3);
  int high = (bitmask >> 4) & 0xF;
  int cntHigh = (high & 0x5) + ((high >> 1) & 0x5);
  cntHigh = (cntHigh & 0x3) + ((cntHigh >> 2) & 0x3);
  return cntLow == 2 && cntHigh == 1;
}

