@pragma('vm:entry-point')
int passwordRuleTraceScore(String log) {
  var stack = <int>[];
  var score = 0;
  const points = {'U': 3, 'D': 2, 'S': 4};
  for (var c in log.split('')) {
    var v = points[c];
    if (v != null) {
      stack.add(v);
      score += v;
    } else if (c == '<' && stack.isNotEmpty) {
      score -= stack.removeLast();
    }
  }
  return score;
}

@pragma('vm:entry-point')
