import 'dart:math';

num typoEditInkBox(List<String> edits) {
  var d = {'ins': [1, 0], 'del': [-1, 0], 'swap': [0, 1], 'case': [0, -1]};
  int x = 0, y = 0, minX = 0, maxX = 0, minY = 0, maxY = 0;
  for (var e in edits) {
    x += d[e]![0];
    y += d[e]![1];
    minX = min(minX, x);
    maxX = max(maxX, x);
    minY = min(minY, y);
    maxY = max(maxY, y);
  }
  return (maxX - minX) * (maxY - minY) + x.abs() + y.abs();
}

@pragma('vm:entry-point')
void main() {
  assert(typoEditInkBox([]) == 0);
  assert(typoEditInkBox(['ins', 'swap']) == 3);
