List<String> annotateLedgerBuffer(List<int> entries) {
  var reserve = 0;
  var out = <String>[];
  for (var v in entries) {
    reserve += v;
    if (reserve < 0) {
      reserve = 0;
    }
    if (reserve >= 5) {
      out.add('stable');
    } else {
      out.add(reserve == 0 ? 'overdrawn' : 'watch');
    }
  }
  return out;
}

