@pragma('vm:entry-point')
String simplifyVoteRatio(int votesA, int votesB) {
  if (votesA == 0 && votesB == 0) return "0 : 0";
  int a = votesA, b = votesB;
  while (b != 0) {
    int temp = b;
    b = a % b;
    a = temp;
  }
  int gcd = a;
  return "${votesA ~/ gcd} : ${votesB ~/ gcd}";
}

@pragma('vm:entry-point')
