List<String> extractTelemetryReports(List<String> events) {
  var stack = <String>[];
  var reports = <String>[];
  for (var e in events) {
    if (e == "POP") {
      if (stack.isNotEmpty) stack.removeLast();
    } else if (e == "REPORT") {
