@pragma('vm:entry-point')
String soilMoistureRecoveryBand(List<List<int>> grid) {
  int best = 0, run = 0, prev = -1;
  for (var row in grid) {
    int s = row.fold(0, (a, b) => a + b);
    run = s >= prev ? run + 1 : 1;
    if (run > best) best = run;
    prev = s;
  }
  return best > 2 ? 'recovering' : 'patchy';
}

@pragma('vm:entry-point')
