String sortPixelIndicesByLuminance(List<List<int>> pixels) {
  var indexed = List.generate(pixels.length, (i) => i);
  indexed.sort((a, b) {
    double lumA = 0.299 * pixels[a][0] + 0.587 * pixels[a][1] + 0.114 * pixels[a][2];
    double lumB = 0.299 * pixels[b][0] + 0.587 * pixels[b][1] + 0.114 * pixels[b][2];
    if (lumA != lumB) return lumA.compareTo(lumB);
    return a.compareTo(b);
  });
  return indexed.join(',');
}

