@pragma('vm:entry-point')
String sortMoistureGridRows(List<String> rows) {
  var sums = <int>[];
  for (var row in rows) {
    var vals = row.split(' ').map(int.parse).toList();
    sums.add(vals.reduce((a,b)=>a+b));
  }
  var indexed = List.generate(rows.length, (i) => i);
  indexed.sort((i,j) => sums[i] != sums[j] ? sums[i].compareTo(sums[j]) : rows[i].split(' ').length.compareTo(rows[j].split(' ').length));
  return indexed.map((i) => rows[i]).join('|');
}

