int firstUnacceptableCorrectionIndex(List<int> sortedEditCosts, int maxCost) {
  int low = 0, high = sortedEditCosts.length;
  while (low < high) {
    int mid = low + (high - low) ~/ 2;
    if (sortedEditCosts[mid] > maxCost) high = mid;
    else low = mid + 1;
  }
  return low < sortedEditCosts.length ? low : -1;
}

