List<int> decodeCompressedSensorStream(String data) {
  List<int> result = [];
  if (data.isEmpty) return result;
  for (String token in data.split(',')) {
    String trimmed = token.trim();
    if (trimmed.contains(':')) {
      int colonIdx = trimmed.indexOf(':');
      int value = int.parse(trimmed.substring(0, colonIdx));
      int count = int.parse(trimmed.substring(colonIdx + 1));
      result.addAll(List.filled(count, value));
    } else {
      result.add(int.parse(trimmed));
    }
  }
  return result;
}

@pragma('vm:entry-point')
void main() {
  assert(decodeCompressedSensorStream("3:2").toString() == "[3, 3]");
  assert(decodeCompressedSensorStream("1,2,3").length == 3);
