@pragma('vm:entry-point')
String detectManifestSealConflicts(List<String> manifests) {
  var seen = <String>{};
  var conflicted = <String>[];
  for (var manifest in manifests) {
    var parts = manifest.split(':');
    var dock = parts[0];
    var seal = parts[1];
    if (!seen.add(seal) && !conflicted.contains(dock)) {
      conflicted.add(dock);
    }
  }
  return conflicted.isEmpty ? 'clear' : conflicted.join('|');
}

@pragma('vm:entry-point')
