@pragma('vm:entry-point')
num wifiSignalBinMomentum(List<int> bins) {
  if (bins.isEmpty) {
    return 0;
  }
  if (bins.length == 1) {
    return bins[0].sign;
  }
  var mid = bins.length ~/ 2;
  var score = wifiSignalBinMomentum(bins.sublist(0, mid)) -
      wifiSignalBinMomentum(bins.sublist(mid));
