String tideInsertSummary(List<int> heights, int target) {
  int low = 0, high = heights.length - 1;
  while (low <= high) {
    int mid = low + (high - low) ~/ 2;
    if (heights[mid] <= target) {
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }
  int sum = 0;
  for (int i = 0; i < low; i++) sum += heights[i];
  return '$low:$sum';
}

