double measureAsciiRowFade(List<int> rowDays) {
  if (rowDays.length < 2) return 0.0;
  int fade = 0;
  for (int i = 1; i < rowDays.length; i++) {
    int gap = rowDays[i] - rowDays[i - 1];
    if (gap > 1) {
      fade += gap - 1;
    } else if (gap < 0) {
      fade += -gap * 2;
    }
  }
  return fade / 2.0;
}

