String shiftDnaByPosition(String dna) {
  StringBuffer sb = StringBuffer();
  for (int i = 0; i < dna.length; i++) {
    String c = dna[i];
    int val;
    if (c == 'A') { val = 0; }
    else if (c == 'C') { val = 1; }
