String prioritizeLedgerFlags(List<String> entries, int floor) {
  var picked = <List<Object>>[];
  for (var e in entries) {
    var p = e.split(':');
    var amount = int.parse(p[1]);
    if (amount.abs() >= floor) picked.add([p[0], amount]);
  }
  picked.sort((a, b) {
    var c = (b[1] as int).abs().compareTo((a[1] as int).abs());
    return c != 0 ? c : (a[0] as String).compareTo(b[0] as String);
  });
  return picked.map((e) => '${e[0]}${(e[1] as int) < 0 ? 'D' : 'C'}').join('|');
}

