int totalDedupedTraversableCost(List<int> cellWeights) {
  List<int> traversable = [];
  for (var w in cellWeights) {
    if (w >= 0) traversable.add(w);
  }
  int total = 0;
  int? prev;
  for (var w in traversable) {
    if (prev == null || w != prev) {
      total += w;
      prev = w;
    }
  }
  return total;
}

