import 'dart:math';

bool elevatorRequestZonesOverlap(List<List<int>> requests) {
  var left = -1 << 30, bottom = -1 << 30, right = 1 << 30, top = 1 << 30;
  for (var r in requests) {
    left = max(left, r[0]);
    bottom = max(bottom, r[1]);
    right = min(right, r[2]);
    top = min(top, r[3]);
  }
  return left <= right && bottom <= top;
}

