double widestBracketSeedGap(List<int> seeds) {
  if (seeds.length < 2) return 0.0;
  var bestGap = -1;
  var cut = 0.0;
  for (var i = 1; i < seeds.length; i++) {
    var gap = seeds[i] - seeds[i - 1];
    if (gap > bestGap) { bestGap = gap; cut = (seeds[i] + seeds[i - 1]) / 2; }
  }
  return cut;
}

