int countRowsWithPathSurplus(List<List<int>> maze, int minSurplus) {
  if (maze.isEmpty) return 0;
  int count = 0;
  int rows = maze.length;
  int cols = maze[0].length;
  for (int i = 0; i < rows; i++) {
    int pathCells = 0;
    for (int j = 0; j < cols; j++) {
      if (maze[i][j] == 0) pathCells++;
    }
    if (2 * pathCells - cols >= minSurplus) count++;
  }
  return count;
}

