List<int> traceCastleDeckBuilds(List<int> cards) {
  var out = List.filled(cards.length, 0);
  for (var i = 0; i < cards.length; i++) {
    out[i] = 1;
    if (cards[i] < 0) {
      out[i] = i == 0 ? 0 : out[i - 1] + 1;
    } else if (i > 0 && cards[i] >= cards[i - 1] && cards[i] - cards[i - 1] <= 2) {
      out[i] = out[i - 1] + 1;
    }
  }
  return out;
}

