@pragma('vm:entry-point')
int chessSquareOctalGcd(int square) {
  int sum = 0, prod = 1, n = square;
  while (n > 0) {
    int d = n % 8;
    sum += d;
    prod *= d;
    n ~/= 8;
  }
  int a = sum, b = prod;
  while (b != 0) {
    int temp = a % b;
    a = b;
    b = temp;
  }
  return a;
}

@pragma('vm:entry-point')
