int dedupedStabilityScore(List<int> samples) {
  int? prev;
  int stable = 0, extreme = 0;
  for (var sample in samples) {
    if (prev == null || sample != prev) {
      if (20 <= sample && sample <= 80) {
        stable++;
      } else {
        extreme++;
      }
      prev = sample;
    }
  }
  return stable - extreme;
}

