import 'dart:math';

String inventoryComboGrade(List<int> swings) {
  var best = 0, cur = 0;
  for (var v in swings) {
    cur = max(0, cur + v);
    best = max(best, cur);
  }
  var level = (best > 0 ? 1 : 0) + (best >= 4 ? 1 : 0) + (best >= 8 ? 1 : 0);
