List<String> stageSeatChartWarnings(List<List<int>> blocks) {
  var out = <String>[];
  for (var i = 0; i < blocks.length; i++) {
    var b = blocks[i];
    var area = (b[2] - b[0]).abs() * (b[3] - b[1]).abs();
    var dist = b[0].abs() + b[1].abs();
    if (area <= 4 && dist <= 3) out.add('front-small-$i');
    if (i > 0) {
      var p = blocks[i - 1];
      var gap = (b[0] - p[2]).abs() + (b[1] - p[3]).abs();
      if (gap == 1) out.add('tight-$i');
    }
  }
  return out;
}

