int tallyTerminalMinuteSwaps(List<int> minutes) {
  var ordered = [...minutes];
  ordered.sort((a, b) {
    var d = (a % 10).compareTo(b % 10);
    if (d != 0) return d;
    return b.compareTo(a);
  });
  var total = 0;
  for (var i = 1; i < ordered.length; i++) {
    if (ordered[i] % 10 == ordered[i - 1] % 10) {
      total += (ordered[i] - ordered[i - 1]).abs();
    }
  }
  return total;
}

