int sumActivePlatformMinutes(List<String> log) {
  var stack = <int>[];
  for (var t in log) {
    if (t == "X") {
      if (stack.isNotEmpty) stack.removeLast();
    } else if (t == "M") {
      if (stack.isNotEmpty) stack.add(stack.last - 1);
    } else {
      stack.add(int.parse(t));
    }
  }
  var total = 0;
  for (var v in stack) total += v;
  return total;
}

