List<int> findElectionCallPoints(List<int> swings) {
  int a = 0, b = swings.length;
  while (a < b) {
    int m = (a + b) >> 1;
    if (swings[m] < 0) a = m + 1; else b = m;
  }
  int c = 0, d = swings.length;
  while (c < d) {
    int m = (c + d) >> 1;
    if (swings[m] < 100) c = m + 1; else d = m;
  }
  return [a == swings.length ? -1 : a, c == swings.length ? -1 : c];
}

