bool bucketChecksumMatches(String report) {
  var parts = report.split('#');
  if (parts.length != 2 || parts[1].isEmpty) return false;
  var sum = 0;
  for (var seg in parts[0].split(',')) {
    if (seg.length < 2) return false;
    sum += seg.codeUnitAt(0) * int.parse(seg.substring(1));
  }
  return sum % 17 == int.parse(parts[1]);
}

