  for (var line in logLines) {
    var parts = line.split(' ');
    int status = int.parse(parts[0]);
    int time = int.parse(parts[1]);
    if (status == 200 && time >= threshold) {
      current++;
      maxStreak = max(maxStreak, current);
    } else {
      current = 0;
    }
  }
  return maxStreak;
}

