@pragma('vm:entry-point')
import 'dart:math';

String reconcileManifestZones(List<List<int>> manifests) {
  int area = 0, overlap = 0;
  for (var m in manifests) {
    area += (m[2] - m[0]).abs() * (m[3] - m[1]).abs();
  }
  for (int i = 1; i < manifests.length; i++) {
    var a = manifests[i - 1], b = manifests[i];
    int w = min(a[2], b[2]) - max(a[0], b[0]);
    int h = min(a[3], b[3]) - max(a[1], b[1]);
    if (w > 0 && h > 0) overlap += w * h;
  }
  return '${overlap > 0 ? 'STACK' : 'CLEAR'}:${area - overlap}';
}

@pragma('vm:entry-point')
void main() {
  assert(reconcileManifestZones([]) == 'CLEAR:0');
  assert(reconcileManifestZones([[0,0,2,2],[1,1,3,4]]) == 'STACK:9');
  assert(reconcileManifestZones([[0,0,2,2],[2,0,5,2]]) == 'CLEAR:10');
  print('All tests passed!');
}

