List<double> dnaPrimeResidueProfile(String dna) {
  int mod = 0;
  int primeHits = 0;
  int balance = 0;
  for (int i = 0; i < dna.length; i++) {
    int v = 'ACGT'.indexOf(dna[i]);
    mod = (mod * 4 + v) % 8;
    if (mod == 2 || mod == 3 || mod == 5 || mod == 7) {
      primeHits++;
    }
    balance += (v & 1) == 0 ? 1 : -1;
  }
  return [mod.toDouble(), primeHits / 2, balance / 2];
}

