List<int> peakRgbMomentum(List<List<int>> pixels) {
  var best = [0, 0, 0];
  var run = [0, 0, 0];
  for (var p in pixels) {
    for (var i = 0; i < 3; i++) {
      run[i] = p[i] >= 128
          ? run[i] + p[i] - 127
