@pragma('vm:entry-point')
List<int> elevatorDirectionRuns(List<int> floors) {
  var dp = List.filled(floors.length, 1);
  for (var i = 1; i < floors.length; i++) {
    var d = floors[i] - floors[i - 1];
    if (d != 0 && (i < 2 || d * (floors[i - 1] - floors[i - 2]) > 0)) {
      dp[i] = dp[i - 1] + 1;
    }
  }
  return dp;
}

