int sumSoilMoistureAtNonCoprimeIndices(List<List<int>> grid) {
  int sum = 0;
  for (int r = 0; r < grid.length; r++) {
    for (int c = 0; c < grid[r].length; c++) {
      int a = r + 1, b = c + 1;
      while (b != 0) {
        int t = b;
        b = a % b;
        a = t;
      }
      if (a > 1) sum += grid[r][c];
