bool verifySatellitePassChecksum(String encoded, int checksum) {
  int sum = 0;
  int count = 0;
  for (int i = 0; i < encoded.length; i++) {
    int c = encoded.codeUnitAt(i);
    if (c >= 48 && c <= 57) {
      count = count * 10 + c - 48;
