int longestRecountSafeLead(List<int> precinctMargins) {
  var left = 0, sum = 0, best = 0;
  for (var right = 0; right < precinctMargins.length; right++) {
    sum += precinctMargins[right];
    while (sum > 3) sum -= precinctMargins[left++];
