@pragma('vm:entry-point')
int widestRecoveringWifiBand(List<int> bins, int weakLimit) {
  var left = 0, weak = 0, best = 0;
  for (var right = 0; right < bins.length; right++) {
    if (bins[right] < 0) weak++;
    while (weak > weakLimit) {
      if (bins[left] < 0) weak--;
      left++;
    }
    var width = right - left + 1;
    if (width > best && bins[right] >= 0) best = width;
  }
  return best;
