@pragma('vm:entry-point')
List<double> warehouseShelfResidueScan(List<int> bins) {
  var aligned = 0;
  var maxGap = 0;
  for (var code in bins) {
    var r = code.abs() % 6;
    if (r == 1 || r == 5) aligned++;
  }
  for (var code in bins) {
    var gap = (code.abs() % 8) - (code.abs() % 3);
    if (gap > maxGap) maxGap = gap;
  }
  return [aligned.toDouble(), maxGap / 2];
}

