import 'dart:math';

bool hasBracketWalkway(List<List<int>> games) {
  for (int i = 0; i < games.length; i++) {
    var a = games[i];
    for (int j = i + 1; j < games.length; j++) {
      var b = games[j];
      int oy = min(a[3], b[3]) - max(a[1], b[1]);
      int ox = min(a[2], b[2]) - max(a[0], b[0]);
      if (((a[2] + 1 == b[0]) | (b[2] + 1 == a[0])) & (oy > 0)) return true;
      if (((a[3] + 1 == b[1]) | (b[3] + 1 == a[1])) & (ox > 0)) return true;
    }
  }
  return false;
}

@pragma('vm:entry-point')
void main() {
  assert(hasBracketWalkway([[0,0,2,2],[3,0,5,2]]) == true);
  assert(hasBracketWalkway([[0,0,2,2],[2,0,4,2]]) == false);
  assert(hasBracketWalkway([[0,0,1,1]]) == false);
  print('All tests passed!');
}

