@pragma('vm:entry-point')
List<int> compressBarcodeBands(String digits, int seed) {
  var out = <int>[];
  var run = 0;
  for (var i = 0; i < digits.length; i++) {
    run++;
    if (i == digits.length - 1 || digits[i] != digits[i + 1]) {
      var d = digits.codeUnitAt(i) - 48;
      out.add(((d + seed) % 10) * 10 + run);
      run = 0;
    }
  }
  return out;
}

