@pragma('vm:entry-point')
bool hasWrappedTypoParity(List<int> edits) {
  var seen = 0;
  var active = 0;
  for (final m in edits) {
    var v = m & 31;
    if (v == 0 || (v & (v - 1)) != 0) return false;
    active |= v;
    seen ^= v;
  }
  var rotated = ((active << 1) | (active >> 4)) & 31;
  return edits.isNotEmpty && seen == rotated;
}

@pragma('vm:entry-point')
void main() {
  assert(hasWrappedTypoParity([1, 2, 4, 8, 16]) == true);
  assert(hasWrappedTypoParity([1, 2, 4, 8]) == false);
  assert(hasWrappedTypoParity([3]) == false);
  print('All tests passed!');
}

