List<List<int>> mapPacketProbeSlots(List<int> data) {
  int s = data.indexOf(-1);
  if (s < 0) return [];
  List<int> a = data.sublist(0, s), outQ = data.sublist(s + 1);
  List<List<int>> out = [];
  for (int q in outQ) {
    int l = 0, r = a.length;
    while (l < r) {
      int m = (l + r) >> 1;
      if (a[m] < q) l = m + 1;
      else r = m;
    }
    out.add([q, l]);
  }
  return out;
}

