bool shelfCodeRollbackStable(String log) {
  var stack = <String>[];
  for (var ch in log.split('')) {
    if (ch == '<') {
      if (stack.isEmpty) return false;
      stack.removeLast();
    } else if (stack.isNotEmpty && stack.last == ch) {
      stack.removeLast();
    } else {
      stack.add(ch);
    }
  }
  return stack.length <= 1;
}

