    int span = 1;
    if (tape.codeUnitAt(i) == 45) span = 3;
    if (tape.codeUnitAt(i) == 47) span = 2;
    day += span;
    if (day % 7 == 0 || day % 7 == 6) hits++;
  }
  return hits;
}

