bool hasSingleWifiDeadZoneTransition(int bins) {
  int strong = 0;
  int transitions = 0;
  int first = bins & 3;
  int prev = first;
  strong += first == 3 ? 1 : 0;
  for (int i = 1; i < 8; i++) {
    int cur = (bins >> (i * 2)) & 3;
    if ((prev ^ cur) == 3) transitions++;
    strong += cur == 3 ? 1 : 0;
    prev = cur;
  }
  if ((prev ^ first) == 3) transitions++;
  return transitions == 1 && strong >= 2;
}

