@pragma('vm:entry-point')
List<int> bracketVenueMetrics(List<int> venues, int r) {
  var overlaps = 0, route = 0;
  for (var i = 0; i + 3 < venues.length; i += 2) {
    route += (venues[i] - venues[i + 2]).abs() +
        (venues[i + 1] - venues[i + 3]).abs();
  }
  for (var i = 0; i < venues.length; i += 2) {
    for (var j = i + 2; j < venues.length; j += 2) {
      if ((venues[i] - venues[j]).abs() <= r * 2 &&
          (venues[i + 1] - venues[j + 1]).abs() <= r * 2) overlaps++;
    }
  }
  return [route, overlaps];
}

