String shiftTimetableMinutes(String t, int s) {
  if (t.isEmpty) return t;
  return t.split(',').map((p) {
    var hm = p.split(':');
    int h = int.parse(hm[0]), m = int.parse(hm[1]);
    m = ((m + s) % 60 + 60) % 60;
