@pragma('vm:entry-point')
String sourdoughStarterScaling(List<int> bakeDays, int reuseWindow) {
  if (bakeDays.isEmpty) return '';
  var scale = 1;
  var plan = <String>['${bakeDays[0]}:1'];
  for (var i = 1; i < bakeDays.length; i++) {
    if (bakeDays[i] - bakeDays[i - 1] <= reuseWindow) {
      scale++;
    } else {
      scale = 1;
    }
    plan.add('${bakeDays[i]}:$scale');
  }
  return plan.join(',');
}

