String warehouseUrgentPickSequence(List<String> bins) {
  var items = [...bins];
  items.sort((a, b) {
    var pa = a.split(':');
    var pb = b.split(':');
    var qa = int.parse(pa[1]);
    var qb = int.parse(pb[1]);
