import 'dart:math';

bool hasContinuousPassCoverage(List<List<int>> passes, int requiredDuration) {
  if (passes.isEmpty) return false;
  passes.sort((a, b) => a[0].compareTo(b[0]));
  int curStart = passes[0][0], curEnd = passes[0][1], maxLen = curEnd - curStart;
  for (int i = 1; i < passes.length; i++) { if (passes[i][0] <= curEnd) { curEnd = max(curEnd, passes[i][1]); } else { curStart = passes[i][0]; curEnd = passes[i][1]; } maxLen = max(maxLen, curEnd - curStart); }
  return maxLen >= requiredDuration;
}

