@pragma('vm:entry-point')
List<int> longestStableTelemetryRun(List<int> samples, int jumpLimit) {
  var bestStart = 0;
  var bestLen = 0;
  var left = 0;
  for (var i = 0; i < samples.length; i++) {
    if (i > 0 && (samples[i] - samples[i - 1]).abs() > jumpLimit) {
      left = i;
    }
    if (i - left + 1 > bestLen) {
      bestLen = i - left + 1;
      bestStart = left;
    }
  }
  return bestLen == 0 ? [] : [bestStart, bestStart + bestLen - 1];
}

