@pragma('vm:entry-point')
int findFirstTideAboveMean(List<int> tideHeights) {
  if (tideHeights.isEmpty) return -1;
  int total = 0, len = tideHeights.length;
  for (int h in tideHeights) total += h;
  int left = 0, right = len - 1, ans = -1;
  while (left <= right) {
    int mid = (left + right) ~/ 2;
    if (tideHeights[mid] * len > total) {
      ans = mid;
      right = mid - 1;
    } else {
      left = mid + 1;
    }
  }
  return ans;
}

