int passwordZoneOverlap(String password, int limit) {
  var score = 0;
  for (var i = 1; i < password.length; i++) {
    var a = password.codeUnitAt(i - 1) % 10;
    var b = password.codeUnitAt(i) % 10;
    var dx = (a - b).abs();
    if (dx + 1 <= limit) {
