@pragma('vm:entry-point')
double tideAsymmetryIndex(List<double> readings, double target) {
  var groups = <bool, List<double>>{true: [], false: []};
  for (var r in readings) {
    if (r > target) {
      groups[true]!.add(r);
    } else if (r < target) {
      groups[false]!.add(r);
    }
  }
  if (groups[true]!.isEmpty || groups[false]!.isEmpty) return 0.0;
  double aboveAvg = groups[true]!.fold(0.0, (sum, r) => sum + r - target) / groups[true]!.length;
  double belowAvg = groups[false]!.fold(0.0, (sum, r) => sum + target - r) / groups[false]!.length;
  return aboveAvg / belowAvg;
}

@pragma('vm:entry-point')
