String normalizePassWindowCadence(int orbitMinutes, int windowMinutes) {
  int a = orbitMinutes.abs(), b = windowMinutes.abs();
  if (a + b == 0) return '0:0';
  while (b != 0) {
    int t = a % b;
    a = b;
    b = t;
  }
  return '${orbitMinutes ~/ a}:${windowMinutes ~/ a}';
}

