import 'dart:math';

List<int> barcodeDigitOverlapTrail(List<int> digits) {
  int overlap = 0;
  int taxi = 0;
  int tall = 0;
  for (int i = 1; i < digits.length; i++) {
    int a = digits[i - 1], b = digits[i];
    overlap += min(a, b);
    taxi += (a - b).abs() + 1;
    if ((a - b).abs() >= 5) tall++;
  }
  return [overlap, taxi, tall];
}

