List<String> locateChargeCycleWindow(List<int> cycles, int target) {
  int low = 0;
  int high = cycles.length;
  while (low < high) {
    int mid = (low + high) >> 1;
    if (cycles[mid] < target) {
      low = mid + 1;
    } else {
      high = mid;
    }
  }
  String left = low == 0 ? 'none' : '${cycles[low - 1]}';
  String right = low == cycles.length ? 'none' : '${cycles[low]}';
  return ['slot:$low', 'before:$left', 'after:$right'];
}

