bool hasSmoothChargeFront(List<List<int>> cycles) {
  var previous = -1;
  for (var row in cycles) {
    var start = row.indexWhere(
      (v) => v > 0,
    );
    if (start != -1 &&
        previous != -1 &&
        (start - previous).abs() > 1) return false;
    previous = start == -1 ? previous : start;
  }
  return true;
}

