import 'dart:math';

int countRoundingDirectionFlips(List<int> cents) {
  var v = List<int>.from(cents);
  v.sort((a, b) {
    int da = min(a % 5, 5 - a % 5);
    int db = min(b % 5, 5 - b % 5);
    int c = da - db;
    return c != 0 ? c : b - a;
  });
  int flips = 0;
  for (int i = 1; i < v.length; i++) {
    if ((v[i] % 5 >= 3) != (v[i - 1] % 5 >= 3)) flips++;
  }
  return flips;
}

