@pragma('vm:entry-point')
bool hasRollingServerOutageBurst(List<String> logs) {
  int streak = 0, prevDay = -1000;
  for (var line in logs) {
    var parts = line.split(':');
    int day = int.parse(parts[0]);
    int minutes = int.parse(parts[1]);
    if (day == prevDay + 1 && minutes >= 30) {
      streak += minutes;
    } else {
      streak = minutes >= 30 ? minutes : 0;
    }
    if (streak >= 180) return true;
    prevDay = day;
  }
  return false;
}

