@pragma('vm:entry-point')
List<List<int>> collapseHashBucketCounts(String trace) {
  var out = <List<int>>[];
  for (var part in trace.split(',')) {
    if (part.isEmpty) continue;
    var s = part.split('#');
    var bucket = int.parse(s[0]);
    var count = int.parse(s[1]);
    if (out.isNotEmpty && out.last[0] == bucket) {
      out.last[1] += count;
    } else {
      out.add([bucket, count]);
    }
  }
  return out.where((e) => e[1] != 0).toList();
}

@pragma('vm:entry-point')
void main() {
  assert(collapseHashBucketCounts('').toString() == '[]');
  assert(collapseHashBucketCounts('3#2,3#-2').toString() == '[]');
  assert(collapseHashBucketCounts('1#4,1#1,2#3').toString() == '[[1, 5], [2, 3]]');
  print('All tests passed!');
}

