List<int> thermostatDriftCredits(List<int> targets) {
  var out = <int>[];
  var carry = 0;
  for (var t in targets) {
    var next = carry;
    if (t >= 24) next += 2;
    else next = next > 0 ? next - 1 : 0;
    if (t <= 18 && next > 0) next--;
    out.add(next);
    carry = next;
  }
  return out;
}

