int countAdjacentBitOverlapPairs(String sequence) {
  if (sequence.length < 2) return 0;
  const baseBits = {'A':0,'C':1,'G':2,'T':3};
  int count = 0;
  for (int i = 0; i < sequence.length - 1; i++) {
