int chargeCycleStepGcd(List<int> levels) {
  int g = 0;
  for (int i = 1; i < levels.length; i++) {
    int d = (levels[i] - levels[i - 1]).abs();
    if (d > 0) {
      while (g != 0 && d != 0) {
        int t = g % d;
        g = d;
        d = t;
      }
      if (g == 0) g = d;
    }
  }
  return g;
}

