String qrTimingPatternModuleColor(List<int> runLengths, int k) {
  int sum = 0;
  for (int i = 0; i < runLengths.length; i++) {
    sum += runLengths[i];
    if (sum >= k) {
      return i.isEven ? "dark" : "light";
    }
  }
  return "unknown";
}

