@pragma('vm:entry-point')
bool containsTargetGrayPixel(List<int> data) {
  int target = (data.isEmpty ? -1 : data[0]) * 65793;
  int lo = 1;
  int hi = data.length - 1;
  while (lo <= hi) {
    int mid = (lo + hi) >> 1;
    int v = data[mid];
    if (v == target) return true;
    if (v < target) {
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  return false;
}

