int countAlternatingPeakGlyphs(List<String> rows, int row, String glyph) {
  if (row >= rows.length) return 0;
  int hits = 0;
  String line = rows[row];
  for (int i = 0; i < line.length; i++) {
    if (line[i] == glyph && i * 2 == line.length - 1) {
      hits++;
