@pragma('vm:entry-point')
int countCentRoundingBias(List<List<int>> amounts, int step) {
  var bias = 0;
  for (var row in amounts) {
    for (var cents in row) {
      var rem = cents % step;
      if (rem * 2 >= step) {
        bias += step - rem;
      } else {
        bias -= rem;
      }
    }
  }
  return bias;
}

@pragma('vm:entry-point')
void main() {
  assert(countCentRoundingBias([[12, 13], [14, 15]], 5) == 1);
  assert(countCentRoundingBias([[5], [15]], 10) == 10);
  assert(countCentRoundingBias([], 5) == 0);
  print('All tests passed!');
}

