List<double> sumOfRgbComponentDigitsInBase(List<int> rgb, int base) {
  if (rgb.isEmpty) return <double>[];
  List<double> result = [];
  for (int component in rgb) {
    int sum = 0;
    int n = component;
    while (n > 0) {
      sum += n % base;
      n ~/= base;
