List<int> longestHomeWinStreak(List<int> diffs) {
  int maxLen = 0, maxStart = 0, start = 0;
  for (int i = 0; i <= diffs.length; i++) {
    if (i == diffs.length || diffs[i] <= 0) {
      int len = i - start;
      if (len > maxLen) { maxLen = len; maxStart = start; }
      start = i + 1;
    }
  }
  return diffs.sublist(maxStart, maxStart + maxLen);
}

