String seatingChartChecksumShift(String seats) {
  if (seats.isEmpty) return '';
  int checksum = 0;
  for (var p in seats.split(',')) {
    checksum += (p.codeUnitAt(0) - 64) * int.parse(p.substring(1));
  }
  int shift = checksum % 26;
  var out = <String>[];
  for (var p in seats.split(',')) {
    int c = p.codeUnitAt(0) - 65;
    out.add(String.fromCharCode((c + shift) % 26 + 65) + p.substring(1));
  }
  return out.join(',');
}

