bool followsPacketSizeDrift(List<List<int>> packetGrid, int drift) {
  var ok = true;
  for (var row in packetGrid) {
    var seen = row.length < 2;
    for (var i = 1; i < row.length; i++) {
      if (row[i] - row[i - 1] == drift) {
        seen = true;
      } else if (row[i] != row[i - 1]) {
        ok = false;
      }
    }
    ok = ok && seen;
  }
  return ok;
}

