@pragma('vm:entry-point')
import 'dart:math';

String mazePocketLabel(List<List<int>> cells, int sx, int sy) {
  if (cells.isEmpty) return 'void';
  int minX = cells[0][0], maxX = minX, minY = cells[0][1], maxY = minY, near = 0;
  for (var c in cells) {
    minX = min(minX, c[0]);
    maxX = max(maxX, c[0]);
    minY = min(minY, c[1]);
    maxY = max(maxY, c[1]);
    if ((c[0] - sx).abs() + (c[1] - sy).abs() <= 1) near++;
  }
  int gaps = (maxX - minX + 1) * (maxY - minY + 1) - cells.length;
  return near > gaps ? 'sealed:$near' : 'open:$gaps';
}

@pragma('vm:entry-point')
void main() {
  assert(mazePocketLabel([], 0, 0) == 'void');
  assert(mazePocketLabel([[0, 0]], 0, 0) == 'sealed:1');
  assert(mazePocketLabel([[0, 0], [2, 0]], 0, 1) == 'open:1');
  print('All tests passed!');
}

