List<int> findManifestClearanceBoundary(List<int> manifests) {
  int l = 0, r = manifests.length;
  while (l < r) {
    int m = (l + r) >> 1;
    if (manifests[m] < 0) l = m + 1; else r = m;
  }
  return [l - 1, l];
}

