@pragma('vm:entry-point')
String mostFrequentTrainMinutes(List<int> departureTimes) {
  var freq = <int, int>{};
  for (var t in departureTimes) {
    freq[t % 60] = (freq[t % 60] ?? 0) + 1;
  }
  int max = 0;
  var best = <int>[];
  for (var e in freq.entries) {
    if (e.value > max) { max = e.value; best = [e.key]; } else if (e.value == max) { best.add(e.key); }
  }
  best.sort();
  return best.join(':');
}

