int sensorTelemetryParityMask(int telemetry) {
  int mask = 0;
  int index = 0;
  while (telemetry != 0) {
    int sample = telemetry & 15;
    int parity = (sample & 1) ^ ((sample >> 1) & 1) ^ ((sample >> 2) & 1);
    if (parity != ((sample >> 3) & 1)) {
      mask |= 1 << index;
    }
    telemetry >>= 4;
    index++;
  }
  return mask;
}

