int longestBucketRotationGap(List<int> bucketAdds) {
  int carry = 0;
  int last = -1;
  int best = 0;
  for (int i = 0; i < bucketAdds.length; i++) {
    carry += bucketAdds[i];
    if (carry >= 10) {
      int gap = last < 0 ? i + 1 : i - last;
      if (gap > best) best = gap;
      last = i;
      carry %= 10;
    }
  }
  return best;
}

