List<String> groupDevicesBySignalBin(List<String> deviceReadings) {
  var bins = {'Excellent':<String>[], 'Good':[], 'Fair':[], 'Poor':[]};
  for (var reading in deviceReadings) {
    var parts = reading.split(':');
    var device = parts[0];
    var signal = int.parse(parts[1]);
    if (signal >= -50) bins['Excellent']!.add(device);
    else if (signal >= -60) bins['Good']!.add(device);
    else if (signal >= -70) bins['Fair']!.add(device);
    else bins['Poor']!.add(device);
  }
  return bins.entries.where((e) => e.value.isNotEmpty).map((e) => '${e.key}: ${e.value.join(', ')}').toList();
}

