int serverErrorManhattan(List<List<int>> logs) {
  int sum = 0;
  List<int>? prev;
  for (final log in logs) {
    if (log[1] >= 3) {
      if (prev != null) {
        sum += (log[0] - prev[0]).abs() + (log[1] - prev[1]).abs();
      }
