import 'dart:math';
String cardBoundingBoxArea(List<List<int>> cards) {
  if (cards.isEmpty) return 'Area: 0';
  int minX = cards[0][0], maxX = minX, minY = cards[0][1], maxY = minY;
  for (final c in cards) { minX = min(minX, c[0]); maxX = max(maxX, c[0]); minY = min(minY, c[1]); maxY = max(maxY, c[1]); }
  int area = (maxX - minX + 1) * (maxY - minY + 1);
  return 'Area: $area';
}

@pragma('vm:entry-point')
void main() {
  assert(cardBoundingBoxArea([]) == 'Area: 0');
  assert(cardBoundingBoxArea([[0,0]]) == 'Area: 1');
  assert(cardBoundingBoxArea([[0,0],[1,2]]) == 'Area: 6');
  print('All tests passed!');
}

tests:
void main() {
  final candidate = cardBoundingBoxArea;

  expect(candidate([]), 'Area: 0');
  expect(candidate([[0,0]]), 'Area: 1');
  expect(candidate([[0,0],[0,2]]), 'Area: 3');
  expect(candidate([[1,2],[3,4]]), 'Area: 9');
  expect(candidate([[-2,-3],[-5,-1]]), 'Area: 12');
  expect(candidate([[10,10],[10,10],[10,10]]), 'Area: 1');
  expect(candidate([[-1000,-1000],[1000,1000]]), 'Area: 4004001');
  expect(candidate([[0,5],[100,5]]), 'Area: 101');
  expect(candidate([[7,0],[7,50]]), 'Area: 51');
  expect(candidate([[1,2],[2,1],[3,2],[2,3]]), 'Area: 9');
  expect(candidate([[5,5]]), 'Area: 1');
}

