@pragma('vm:entry-point')
List<String> locateShelfGapNeighbors(List<String> shelfCodes, String missingCode) {
  int lo = 0;
  int hi = shelfCodes.length;
  while (lo < hi) {
    int mid = (lo + hi) >> 1;
    if (shelfCodes[mid].compareTo(missingCode) < 0) {
      lo = mid + 1;
    } else {
      hi = mid;
    }
  }
  List<String> out = [];
  if (lo > 0) out.add(shelfCodes[lo - 1]);
  if (lo < shelfCodes.length) out.add(shelfCodes[lo]);
  return out;
}

@pragma('vm:entry-point')
void main() {
  assert(locateShelfGapNeighbors(['A10','A20','A40'], 'A30').toString() == '[A20, A40]');
  assert(locateShelfGapNeighbors([], 'B10').toString() == '[]');
  assert(locateShelfGapNeighbors(['C05'], 'C01').toString() == '[C05]');
  print('All tests passed!');
}

