@pragma('vm:entry-point')
int calculateTransitionBias(String dna) {
  int purineToPyrimidine = 0;
  int pyrimidineToPurine = 0;
  for (int i = 0; i < dna.length - 1; i++) {
    if ('AG'.contains(dna[i]) && 'CT'.contains(dna[i+1])) {
      purineToPyrimidine++;
    }
  }
  for (int i = 0; i < dna.length - 1; i++) {
    if ('CT'.contains(dna[i]) && 'AG'.contains(dna[i+1])) {
      pyrimidineToPurine++;
    }
  }
  return purineToPyrimidine - pyrimidineToPurine;
}

@pragma('vm:entry-point')
void main() {
  assert(calculateTransitionBias("") == 0);
  assert(calculateTransitionBias("AC") == 1);
  assert(calculateTransitionBias("CA") == -1);
