int firstRoundExceedingMedianSeed(List<int> seeds) {
  if (seeds.isEmpty) return -1;
  int t = (seeds.first + seeds.last) ~/ 2, l = 0, r = seeds.length;
  while (l < r) {
    int m = (l + r) >> 1;
    if (seeds[m] <= t) l = m + 1; else r = m;
  }
  return l;
}

