@pragma('vm:entry-point')
int calculateBackorderAlertScore(List<Map<String, int>> reports) {
  var flagged = <int>{};
  var score = 0;
  for (final report in reports) {
    var sku = report['sku']!;
    var available = report['stock']! - report['reserved']!;
    if (available <= 2 && flagged.add(sku)) {
      score += available < 0 ? 5 : 1;
    }
  }
  return score;
}

@pragma('vm:entry-point')
void main() {
  assert(calculateBackorderAlertScore([]) == 0);
  assert(calculateBackorderAlertScore([{'sku': 4, 'stock': 2, 'reserved': 0}]) == 1);
