@pragma('vm:entry-point')
int countIsolatedGreenPhases(int phaseBits) {
  int x = phaseBits & 0xffff;
  int neighbors = ((x << 1) & 0xffff) | (x >> 1) | ((x & 1) << 15) | (x >> 15);
  int isolated = x & ~neighbors;
  int count = 0;
  for (; isolated != 0; isolated &= isolated - 1) count++;
  return count;
}

@pragma('vm:entry-point')
void main() {
  assert(countIsolatedGreenPhases(0) == 0);
  assert(countIsolatedGreenPhases(0xAAAA) == 8);
