List<int> splitGcDriftLeaves(String dna, int depth) {
  if (depth < 1 || dna.length < 2) {
    return [dna.replaceAll(RegExp(r'[^G]'), '').length - dna.replaceAll(RegExp(r'[^C]'), '').length];
  }
  var m = dna.length ~/ 2;
  return [...splitGcDriftLeaves(dna.substring(0, m), depth - 1), ...splitGcDriftLeaves(dna.substring(m), depth - 1)];
