@pragma('vm:entry-point')
List<int> parseWifiSignalBins(String signalStr) {
  List<int> bins = [0,0,0,0];
  for (String s in signalStr.split(',').where((s) => s.trim().isNotEmpty)) {
    int v = int.parse(s.trim());
    bins[v < -80 ? 0 : v < -70 ? 1 : v < -60 ? 2 : 3]++;
  }
  return bins;
}

@pragma('vm:entry-point')
void main() {
  assert(parseWifiSignalBins('-85, -70').toString() == '[1, 0, 1, 0]');
  assert(parseWifiSignalBins('').toString() == '[0, 0, 0, 0]');
  assert(parseWifiSignalBins('-80, -60, -59').toString() == '[0, 1, 0, 2]');
  print('All tests passed!');
}

tests:
