@pragma('vm:entry-point')
List<int> encodeAsciiRunBases(String row, int base) {
  var out = <int>[], run = 0;
  for (var i = 0; i <= row.length; i++) {
    var fill = i < row.length && row[i] != ' ';
    if (fill) run++;
    else if (run > 0) {
      var part = <int>[];
      while (run > 0) { part.add(run % base); run ~/= base; }
      out..addAll(part.reversed)..add(-1);
    }
  }
  if (out.isNotEmpty) out.removeLast();
  return out;
}

@pragma('vm:entry-point')
void main() {
  assert(encodeAsciiRunBases("## ###", 2).toString() == "[1, 0, -1, 1, 1]");
  assert(encodeAsciiRunBases("", 3).isEmpty);
