String findThresholdExcess(List<double> telemetry) {
  if (telemetry.isEmpty) return "No data";
  double limit = (telemetry.first + telemetry.last) / 2;
  int low = 0, high = telemetry.length;
  while (low < high) {
    int mid = (low + high) ~/ 2;
    if (telemetry[mid] > limit) high = mid;
    else low = mid + 1;
  }
  if (low == telemetry.length) return "No excess";
  return "Excess at index $low (${telemetry[low]})";
}

