bool hasMoreTelemetryBelowThreshold(List<int> sortedTelemetry, int threshold) {
  int left = 0, right = sortedTelemetry.length;
  while (left < right) {
    int mid = (left + right) ~/ 2;
    if (sortedTelemetry[mid] < threshold) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }
  int below = left;
  int aboveOrEqual = sortedTelemetry.length - below;
  return below > aboveOrEqual;
}

