List<int> bracketUpsetSignals(List<int> rounds, int vipMask) {
  var out = <int>[];
  for (var i = 0; i < rounds.length; i++) {
    var s = i & 7;
    var r = ((rounds[i] << s) | (rounds[i] >> (8 - s))) & 255;
    var overlap = r & vipMask;
    var bits = 0;
    while (overlap != 0) {
      bits += overlap & 1;
      overlap >>= 1;
    }
    out.add((r & 1) == 0 ? bits : -bits);
  }
  return out;
}

