@pragma('vm:entry-point')
double averageFloorRequestSpan(List<List<int>> floorRequests) {
  if (floorRequests.isEmpty) return 0.0;
  int rows = floorRequests.length, cols = floorRequests[0].length;
  int totalWeight = 0;
  double totalDistance = 0.0;
  for (int i = 0; i < rows * cols; i++) {
    int r = i ~/ cols, c = i % cols, val = floorRequests[r][c];
    if (val != 0) {
      totalWeight += val;
      totalDistance += val * (r - c).abs();
    }
  }
  return totalWeight == 0 ? 0.0 : totalDistance / totalWeight;
}

