String chessColorStreakCode(List<String> squares) {
  var p = -1, c = 0, b = [0, 0];
  for (final s in squares) {
    var k = (s.codeUnitAt(0) + s.codeUnitAt(1)) & 1;
    c = k == p ? c + 1 : 1;
    if (c > b[k]) b[k] = c;
    p = k;
  }
  return '${b[0]}:${b[1]}';
}

