List<String> classifyUniquePassWindows(List<String> windows) {
  var out = <String>[];
  var seen = <String>{};
  for (var w in windows) {
    var parts = w.split('/');
    var duration = int.parse(parts[2]) - int.parse(parts[1]);
    var key = '${parts[0]}:$duration';
    if (!seen.add(key)) continue;
    var band = duration >= 6 ? 'wide' : 'tight';
    out.add('${parts[0]}:$band:$duration');
  }
  return out;
}

