String groupTrainsByRoundedMinute(List<int> departures, int roundTo) {
  var counts = <int, int>{};
  for (var m in departures) {
    int rounded = ((2 * m + roundTo) ~/ (2 * roundTo)) * roundTo;
    counts.update(rounded, (v) => v + 1, ifAbsent: () => 1);
