List<int> theaterExpansionScores(List<List<int>> chart) {
  var out = <int>[];
  var prev = -1, score = 0;
  for (var row in chart) {
    var open = 0;
    for (var seat in row) {
      if (seat == 0) open++;
    }
    score = open >= prev ? score + open : open;
    out.add(score);
    prev = open;
  }
  return out;
}

