@pragma('vm:entry-point')
int findMissingPairedInventorySlot(List<int> slots) {
  if (slots.isEmpty) return 0;
  int lo = 0, hi = slots.length - 1;
  while (lo < hi) {
    int mid = (lo + hi) ~/ 2;
    if (mid.isOdd) mid--;
    if (mid + 1 < slots.length && slots[mid + 1] == slots[mid] + 1) {
      lo = mid + 2;
    } else {
      hi = mid;
    }
  }
  return slots[lo] + 1;
}

