int roundedWeeklyNetCents(List<int> dailyNetCents) {
  int totalRounded = 0;
  int weekSum = 0;
  int days = dailyNetCents.length;
  for (int i = 0; i < days; i++) {
    weekSum += dailyNetCents[i];
    if (i % 7 == 6) {
      totalRounded += ((weekSum / 5).round() * 5).toInt();
      weekSum = 0;
    } else if (i == days - 1) {
      totalRounded += ((weekSum / 5).round() * 5).toInt();
    }
  }
  return totalRounded;
}

