@pragma('vm:entry-point')
int calculateThermostatDriftScore(List<int> schedule) {
  var blocks = <int>[];
  for (var t in schedule) {
    if (blocks.isEmpty || blocks.last != t) blocks.add(t);
  }
  var score = 0;
  for (var i = 1; i < blocks.length; i++) {
    var diff = (blocks[i] - blocks[i - 1]).abs();
    if (diff >= 4) score += 2;
    else if (diff == 1) score -= 1;
    else score += diff - 1;
  }
  return score;
}

