@pragma('vm:entry-point')
String formatSeatAvailabilityChart(List<String> reservedSeats, int totalRows, int seatsPerRow) {
  var occupied = reservedSeats.toSet();
  var sb = StringBuffer();
  for (int r = 0; r < totalRows; r++) {
    var rowChar = String.fromCharCode(65 + r);
    sb.write('$rowChar: ');
    var statuses = List.generate(seatsPerRow, (s) => occupied.contains('$rowChar${s+1}') ? 'R' : 'A');
    sb.write(statuses.join('_'));
    if (r < totalRows - 1) sb.write(' ; ');
  }
  return sb.toString();
}

@pragma('vm:entry-point')
void main() {
  assert(formatSeatAvailabilityChart([], 1, 1) == 'A: A');
  assert(formatSeatAvailabilityChart(['A1'], 1, 1) == 'A: R');
