String findQrRingDrift(List<int> modules) {
  int lo = 0;
  int hi = modules.length;
  while (lo < hi) {
    int mid = (lo + hi) >> 1;
    int expected = mid * 2 + 1;
    if (modules[mid] == expected) {
      lo = mid + 1;
    } else {
      hi = mid;
    }
  }
  if (lo == modules.length) return 'stable';
  return 'ring$lo';
}

