@pragma('vm:entry-point')
List<List<int>> scaleRecipeWithUndo(List<int> ingredients, List<int> ops) {
  var history = <List<int>>[List<int>.from(ingredients)];
  var stack = <int>[];
  int product = 1;
  for (var op in ops) {
    if (op > 0) { stack.add(op); product *= op; }
    else if (op == 0 && stack.isNotEmpty) product ~/= stack.removeLast();
    history.add(ingredients.map((e) => e * product).toList());
  }
  return history;
}

@pragma('vm:entry-point')
