int computeShelfCodeUndoLedger(String events, int emptyPenalty) {
  var stack = <int>[];
  var score = 0;
  for (var r in events.runes) {
    if (r == 45) {
      score -= stack.isEmpty ? emptyPenalty : stack.removeLast();
    } else {
      var v = r % 10 + 1;
      stack.add(v);
      score += v;
    }
  }
  return score + stack.length;
}

