int countBalancedFaroCuts(List<int> deck, int left, int right) {
  if (right - left < 2) return 0;
  int mid = (left + right) ~/ 2, a = 0, b = 0;
  for (int i = left; i < mid; i++) {
    a += deck[i];
    b += deck[i + mid - left];
  }
  int hit = a == b ? 1 : 0;
  return hit +
      countBalancedFaroCuts(deck, left, mid) +
      countBalancedFaroCuts(deck, mid, right);
}

