List<String> findDiceGateRounds(List<int> rounds) {
  int lo = 0, hi = rounds.length;
  while (lo < hi) {
    int mid = (lo + hi) >> 1;
    if (rounds[mid] < 7) lo = mid + 1; else hi = mid;
  }
  int firstSeven = lo;
  lo = 0;
  hi = rounds.length;
  while (lo < hi) {
    int mid = (lo + hi) >> 1;
    if (rounds[mid] < 11) lo = mid + 1; else hi = mid;
  }
  return ['safe:${firstSeven == rounds.length ? 'none' : firstSeven}', 'jackpot:${lo == rounds.length ? 'none' : lo}'];
}

