List<int> soilMoistureBandOrder(List<List<int>> grid) {
  var ids = List<int>.generate(grid.length, (i) => i);
  int score(List<int> row) {
    var s = 0;
    for (var v in row) {
      if (v < 4) s += 2; else s--;
