double warehouseSplitDrift(List<int> bins, int width) {
  double score = 0.0;
  if (bins.length <= width) {
    for (int i = 1; i < bins.length; i++) {
      if ((bins[i] - bins[i - 1]).abs() > 2) score += 0.5;
    }
  } else {
    int mid = bins.length ~/ 2;
    score = warehouseSplitDrift(bins.sublist(0, mid), width) +
        warehouseSplitDrift(bins.sublist(mid), width);
    if ((bins[mid] - bins[mid - 1]).abs() <= 1) score += 0.25;
  }
  return score;
}

