bool hasRowsWithDuplicateMoisture(List<List<int>> grid, int threshold) {
  int count = 0;
  for (var row in grid) {
    var seen = <int>{};
    bool found = false;
    for (var v in row) {
      if (seen.contains(v)) {
        found = true;
        break;
      }
      seen.add(v);
    }
    if (found) count++;
  }
  return count > threshold;
}

