double mazeCellUndoDensity(List<String> cells) {
  var trail = <String>[];
  double density = 0;
  for (var cell in cells) {
    if (cell == '!') {
      if (trail.isNotEmpty) density -= trail.removeLast().length / 2;
    } else {
      trail.add(cell);
      density += cell.length / 2;
    }
  }
  for (var i = 0; i < trail.length; i++) {
    if (i.isOdd) density += 0.5;
  }
  return density;
}

