int dnaCaesarWeightedSum(String dna) {
  int sum = 0;
  for (int i = 0; i < dna.length; i++) {
    int val;
    String base = dna[i];
    if (base == 'A') val = 1;
    else if (base == 'C') val = 2;
    else if (base == 'G') val = 3;
    else val = 4; // 'T'
    if (val == 4) val = 1;
    else val++;
    sum += (i + 1) * val;
