int circularSuitPairFlags(int deckMask) {
  int flags = 0;
  for (int s = 0; s < 4; s++) {
    int suit = (deckMask >> (s * 13)) & 0x1fff;
    int overlap = suit & ((((suit << 1) & 0x1fff) | (suit >> 12)));
    int count = 0;
    while (overlap != 0) {
      count++;
      overlap &= overlap - 1;
    }
    if (count == 2) flags |= 1 << s;
  }
  return flags;
}

