@pragma('vm:entry-point')
String classifySoilMoistureMask(List<int> rows) {
  int wet = 0, edgeLeaks = 0;
  for (final r in rows) {
    int v = r & 255;
    while (v != 0) {
      wet++;
      v &= v - 1;
    }
    if ((r & 129) != 0) edgeLeaks++;
  }
  int score = wet - edgeLeaks * 2;
  return score > 12 ? 'saturated' : score >= 5 ? 'balanced' : score >= 0 ? 'patchy' : 'cracked';
}

@pragma('vm:entry-point')
void main() {
  assert(classifySoilMoistureMask([]) == 'patchy');
  assert(classifySoilMoistureMask([255, 126]) == 'balanced');
  assert(classifySoilMoistureMask([126, 126, 126]) == 'saturated');
  print('All tests passed!');
}

