String summarizeQrBorderTokens(String rows, int minWidth) {
  var segments = rows.split('/');
  var tokens = <String>[];
  for (var row in segments) {
    var size = row.length;
    if (size >= minWidth && size > 0) {
      var left = row[0];
      var right = row[size - 1];
      tokens.add('$left$right$size');
    }
  }
  return tokens.join(',');
}

