@pragma('vm:entry-point')
num packetBurstImbalance(List<int> packets) {
  if (packets.isEmpty) return 0;
  if (packets.length == 1) return packets[0];
  int mid = packets.length ~/ 2;
  num left = packetBurstImbalance(packets.sublist(0, mid));
  num right = packetBurstImbalance(packets.sublist(mid));
  int edge = packets.first - packets.last;
  if (edge < 0) edge = -edge;
  num drift = left - right;
  return drift + edge;
}

