int passwordStackConcatSum(String password) {
  List<int> stack = [];
  for (int i = 0; i < password.length; i++) {
    String c = password[i];
    if (c.codeUnitAt(0) >= 48 && c.codeUnitAt(0) <= 57) {
      stack.add(int.parse(c));
    } else if (c == '^') {
      if (stack.length < 2) return -1;
      int b = stack.removeLast();
      int a = stack.removeLast();
      stack.add(int.parse('$a$b'));
    }
  }
  return stack.fold(0, (sum, val) => sum + val);
}

@pragma('vm:entry-point')
void main() {
  assert(passwordStackConcatSum("") == 0);
  assert(passwordStackConcatSum("12^") == 12);
  assert(passwordStackConcatSum("^") == -1);
