List<int> barcodeEdgeChecksums(String tape, int span) {
  var out = <int>[];
  var run = '';
  for (var i = 0; i <= tape.length; i++) {
    var c = i < tape.length ? tape[i] : '#';
    if (c.codeUnitAt(0) >= 48 && c.codeUnitAt(0) <= 57) {
      run += c;
    } else if (run.length >= span) {
      out.add(((run.codeUnitAt(0) - 48) + (run.codeUnitAt(run.length - 1) - 48)) % 10);
      run = '';
    } else {
      run = '';
    }
  }
  return out;
}

