List<int> rgbChannelAccumulator(String s) {
  var rgb = [0, 0, 0];
  var m = -1;
  for (var c in s.codeUnits) {
    var p = 'RGB'.indexOf(String.fromCharCode(c));
    if (p >= 0) {
      m = p;
      rgb[m] = 0;
    } else if (m >= 0 && c >= 48 && c <= 57) {
      rgb[m] = (rgb[m] * 10 + c - 48) % 256;
    } else {
      m = -1;
    }
  }
  return rgb;
}

