double rgbPixelUndoGlow(List<String> edits, int bias) {
  var stack = <double>[];
  var total = bias / 2.0;
  for (var e in edits) {
    if (e == 'UNDO') {
      if (stack.isNotEmpty) total -= stack.removeLast();
    } else {
      var v = e == 'R' ? 0.5 : e == 'G' ? 1.0 : 1.5;
      stack.add(v);
      total += v;
    }
  }
  return total;
}

