@pragma('vm:entry-point')
bool bracketTracksMidSeeds(List<List<int>> rounds) {
  for (int i = 1; i < rounds.length; i++) {
    int expected = rounds[i - 1].length ~/ 2;
    if (rounds[i].length != expected) return false;
    for (int j = 0; j < expected; j++) {
      int left = rounds[i - 1][j * 2];
      int right = rounds[i - 1][j * 2 + 1];
      int marker = (left + right) ~/ 2;
      if (rounds[i][j] != marker) return false;
    }
  }
  return true;
}

